\begin{prob} 
Show that the following hold by exhibiting !!{derivation}s from the
axioms:
\begin{enumerate} 
\item $(!A \land !B) \lif (!B \land !A)$
\item $((!A \land !B) \lif !C) \lif (!A \lif (!B \lif !C))$
\item $\lnot(!A \lor !B) \lif \lnot !A$
\end{enumerate} 
\end{prob}
